<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, operationRequest, type AgentNode } from '../api'
import { exactJSON } from '../operations'
import { t } from '../i18n'
import type { GuestDisplay, GuestOptions, GuestSettings } from '../guest'
import GuestDisplayView from './GuestDisplay.vue'
const options=ref<GuestOptions>(),settings=ref<GuestSettings>(),nodes=ref<AgentNode[]>([]),probes=ref<Array<{id:string;name:string}>>([]),preview=ref<GuestDisplay>(),busy=ref(false),error=ref(''),notice=ref('')
const nodeChoices=computed(()=>[...nodes.value,...(settings.value?.nodes??[]).filter(r=>!nodes.value.some(n=>n.nodeId===r.id)).map(r=>({nodeId:r.id,displayName:t('guest.missingResource',{name:r.name})}))])
const probeChoices=computed(()=>[...probes.value,...(settings.value?.probes??[]).filter(r=>!probes.value.some(p=>p.id===r.id)).map(r=>({id:r.id,name:t('guest.missingResource',{name:r.name})}))])

function selected(kind:'nodes'|'probes',id:string){return settings.value?.[kind].find(r=>r.id===id)}
function toggle(kind:'nodes'|'probes',id:string,checked:boolean){if(!settings.value)return;settings.value[kind]=settings.value[kind].filter(r=>r.id!==id);if(checked)settings.value[kind].push({id,name:''});preview.value=undefined}
function name(kind:'nodes'|'probes',id:string,value:string){const resource=selected(kind,id);if(resource)resource.name=value;preview.value=undefined}
async function load(){busy.value=true;error.value='';try{const [config,list,services]=await Promise.all([operationRequest<GuestOptions>('guest.settings'),api.nodes(),operationRequest<{probes:Array<{id:string;name:string}>}>('probes.list')]);options.value=config;settings.value=config.settings;nodes.value=list.nodes.filter(n=>!['pending','revoked'].includes(n.status));probes.value=services.probes}catch(e){error.value=String(e)}finally{busy.value=false}}
async function save(){if(!settings.value)return;busy.value=true;error.value='';notice.value='';preview.value=undefined;try{settings.value=await operationRequest<GuestSettings>('guest.configure',{}, {body:exactJSON(settings.value)});notice.value=t('guest.saved')}catch(e){error.value=String(e)}finally{busy.value=false}}
async function inspect(){busy.value=true;error.value='';try{preview.value=await operationRequest<GuestDisplay>('guest.preview')}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template>
 <section class="guest-settings"><header><h1>{{t('guest.settings')}}</h1><p class="muted">{{t('guest.settingsHint')}}</p></header><p v-if="error" role="alert" class="guest-error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
  <form v-if="settings&&options" @submit.prevent="save"><fieldset :disabled="busy">
   <section class="guest-settings-card"><label class="guest-check"><input v-model="settings.enabled" type="checkbox" />{{t('guest.enabled')}}</label><label>{{t('guest.title')}}<input v-model="settings.title" required /></label><label class="guest-check"><input v-model="settings.showStatus" type="checkbox" />{{t('guest.showStatus')}}</label>
    <h2>{{t('guest.metrics')}}</h2><label v-for="metric in options.metrics" :key="metric.key" class="guest-check"><input v-model="settings.metrics" type="checkbox" :value="metric.key" />{{t(`guest.metric.${metric.key}`)}}</label><label>{{t('guest.history')}}<UiSelect v-model="settings.historyHours"><option v-for="hours in options.historyHours" :key="hours" :value="hours">{{hours===0?t('guest.historyOff'):hours+' '+t('guest.hours')}}</option></UiSelect></label>
   </section>
   <section class="guest-settings-card"><h2>{{t('guest.nodes')}}</h2><p class="muted">{{t('guest.namesHint')}}</p><div v-for="node in nodeChoices" :key="node.nodeId" class="guest-resource"><label class="guest-check"><input type="checkbox" :checked="!!selected('nodes',node.nodeId)" @change="toggle('nodes',node.nodeId,($event.target as HTMLInputElement).checked)" />{{node.displayName}}</label><label v-if="selected('nodes',node.nodeId)">{{t('guest.publicName')}}<input :value="selected('nodes',node.nodeId)?.name" required @input="name('nodes',node.nodeId,($event.target as HTMLInputElement).value)" /></label></div><p v-if="!nodeChoices.length" class="muted">{{t('guest.noNodes')}}</p></section>
   <section class="guest-settings-card"><h2>{{t('guest.services')}}</h2><div v-for="probe in probeChoices" :key="probe.id" class="guest-resource"><label class="guest-check"><input type="checkbox" :checked="!!selected('probes',probe.id)" @change="toggle('probes',probe.id,($event.target as HTMLInputElement).checked)" />{{probe.name}}</label><label v-if="selected('probes',probe.id)">{{t('guest.publicName')}}<input :value="selected('probes',probe.id)?.name" required @input="name('probes',probe.id,($event.target as HTMLInputElement).value)" /></label></div><p v-if="!probeChoices.length" class="muted">{{t('guest.noProbes')}}</p></section>
   <div class="guest-settings-actions"><button class="primary-button" type="submit">{{t('guest.save')}}</button><button type="button" @click="inspect">{{t('guest.preview')}}</button><button type="button" @click="load">{{t('guest.reload')}}</button></div>
  </fieldset></form><GuestDisplayView v-if="preview" :preview="preview" />
 </section>
</template>
<style scoped>
.guest-settings{width:min(1000px,calc(100% - 48px));margin:32px auto 64px;color:var(--text)}h1{font-family:var(--display-font);font-size:clamp(28px,4vw,42px)}fieldset{border:0;margin:0;padding:0;min-width:0}.guest-settings-card{padding:22px;border:1px solid var(--line);border-radius:var(--radius-card);background:var(--surface-soft);margin-bottom:18px}.guest-settings-card label{display:flex;flex-direction:column;gap:7px;margin:14px 0}.guest-settings-card label.guest-check{flex-direction:row;align-items:center;gap:10px}.guest-settings-card input:not([type=checkbox]),.guest-settings-card select{width:100%;max-width:480px;padding:10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--surface);color:var(--text);font:inherit}.guest-check input{width:18px;height:18px;flex:none}.guest-resource{border-top:1px solid var(--line);padding:8px 0;overflow-wrap:anywhere}.guest-settings-actions{display:flex;gap:10px;flex-wrap:wrap}.guest-settings button{font:inherit;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:var(--radius-control);padding:10px 14px;cursor:pointer}.guest-settings button.primary-button{background:var(--accent-soft);color:var(--accent)}.guest-settings button:hover:not(:disabled){border-color:var(--accent)}.guest-settings button:active:not(:disabled){background:var(--accent-soft);color:var(--accent)}.guest-settings button:disabled{opacity:.5;cursor:not-allowed}.guest-error{color:var(--danger);overflow-wrap:anywhere}@media(max-width:700px){.guest-settings{width:calc(100% - 24px);margin:20px auto}.guest-settings-card{padding:16px}}
</style>
